<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue'
import { pb } from '../pocketbase'
import { useI18n } from '../i18n'

type SharedAttachment={reference:string;fileName:string;mediaType:string;size:number;billingAt?:string}
const props=defineProps<{token:string;reference:string;count:number;accountAccess:boolean}>()
const {tr,formatDate}=useI18n()
const dialog=ref<HTMLDialogElement>(),items=ref<SharedAttachment[]>([]),loading=ref(false),error=ref(''),previewUrl=ref(''),previewType=ref(''),previewName=ref(''),activeItem=ref<SharedAttachment>()
let previousFocus:HTMLElement|undefined
function base(){return `/api/subflow/v1/shares/${encodeURIComponent(props.token)}/${props.accountAccess?'account/':''}attachments/`}
function headers(){const h=new Headers({Accept:'application/json'});if(pb.authStore.token)h.set('Authorization',`Bearer ${pb.authStore.token}`);return h}
async function open(){previousFocus=document.activeElement instanceof HTMLElement?document.activeElement:undefined;dialog.value?.showModal();loading.value=true;error.value='';try{const r=await fetch(base()+encodeURIComponent(props.reference),{headers:headers()});if(!r.ok)throw Error();const body=await r.json();items.value=body.data||[]}catch{error.value=tr('shareAttachmentError')}finally{loading.value=false}}
function url(item:SharedAttachment,download=false){return `/api/subflow/v1/shares/${encodeURIComponent(props.token)}/${props.accountAccess?'account/':''}attachment/${encodeURIComponent(item.reference)}${download?'?download=true':''}`}
async function preview(item:SharedAttachment){try{const r=await fetch(url(item),{headers:headers()});if(!r.ok)throw Error();const blob=await r.blob();if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value=URL.createObjectURL(blob);previewType.value=item.mediaType;previewName.value=item.fileName;activeItem.value=item}catch{error.value=tr('attachmentOpenFailed')}}
async function download(item:SharedAttachment){try{const r=await fetch(url(item,true),{headers:headers()});if(!r.ok)throw Error();const blob=await r.blob(),link=document.createElement('a'),objectUrl=URL.createObjectURL(blob);link.href=objectUrl;link.download=item.fileName;link.click();setTimeout(()=>URL.revokeObjectURL(objectUrl),1000)}catch{error.value=tr('attachmentOpenFailed')}}
function close(){dialog.value?.close();if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';previousFocus?.focus();previousFocus=undefined}
function backToList(){if(previewUrl.value)URL.revokeObjectURL(previewUrl.value);previewUrl.value='';activeItem.value=undefined}
onBeforeUnmount(()=>{if(previewUrl.value)URL.revokeObjectURL(previewUrl.value)})
</script>
<template>
  <button v-if="reference&&count" type="button" class="share-attachment-trigger" @click="open"><svg aria-hidden="true" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m8 12.5 6.7-6.7a3.2 3.2 0 0 1 4.5 4.5l-8.5 8.5a5 5 0 0 1-7.1-7.1l8.1-8.1"/></svg>{{tr('shareAttachmentCount',{count})}}</button>
  <Teleport to="body"><dialog ref="dialog" class="share-attachment-dialog" :aria-label="tr('attachments')" @cancel.prevent="close"><header><div><strong>{{previewUrl?previewName:tr('attachments')}}</strong><small v-if="!previewUrl">{{tr('shareAttachmentCount',{count:items.length||count})}}</small></div><button class="icon-button" type="button" :aria-label="tr('close')" @click="previewUrl?backToList():close()">×</button></header><p v-if="loading" role="status">{{tr('shareAttachmentLoading')}}</p><p v-if="error" class="notice danger" role="alert">{{error}}</p><template v-if="previewUrl"><img v-if="previewType.startsWith('image/')" :src="previewUrl" :alt="previewName"><iframe v-else-if="previewType==='application/pdf'" :src="previewUrl" :title="previewName"></iframe><button v-else-if="activeItem" class="primary" type="button" @click="download(activeItem)">{{tr('shareAttachmentDownload')}}</button></template><ul v-else><li v-for="item in items" :key="item.reference"><div><strong>{{item.fileName}}</strong><small v-if="item.billingAt">{{tr('shareAttachmentPeriod',{date:formatDate(item.billingAt)})}}</small><small>{{(item.size/1048576).toFixed(2)}} MB</small></div><button v-if="item.mediaType.startsWith('image/')||item.mediaType==='application/pdf'" class="ghost" type="button" @click="preview(item)">{{tr('shareAttachmentPreview')}}</button><button class="ghost" type="button" @click="download(item)">{{tr('shareAttachmentDownload')}}</button></li></ul></dialog></Teleport>
</template>
<style scoped>
.share-attachment-trigger{display:inline-flex;align-items:center;gap:6px;padding:7px 10px;border:1px solid var(--line);border-radius:9px;background:var(--surface-soft);color:var(--brand);font-size:12px;font-weight:700;cursor:pointer}.share-attachment-dialog{position:fixed;inset:0 0 0 auto;margin:0;width:min(440px,100vw);height:100dvh;max-height:none;padding:20px;border:0;border-left:1px solid var(--line);border-radius:0;background:var(--surface);color:var(--ink);box-shadow:var(--shadow-lg)}.share-attachment-dialog::backdrop{background:#0008}.share-attachment-dialog header{display:flex;justify-content:space-between;align-items:center;gap:12px;padding-bottom:14px;border-bottom:1px solid var(--line)}.share-attachment-dialog header div,.share-attachment-dialog li div{display:grid;gap:4px;min-width:0}.share-attachment-dialog small{color:var(--muted);font-size:12px}.share-attachment-dialog ul{list-style:none;padding:0;margin:0;display:grid}.share-attachment-dialog li{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:14px 0;border-bottom:1px solid var(--line)}.share-attachment-dialog li strong{overflow-wrap:anywhere}.share-attachment-dialog img,.share-attachment-dialog iframe{width:100%;height:calc(100dvh - 100px);object-fit:contain;border:0}.share-attachment-dialog a{text-decoration:none}.share-attachment-trigger:focus-visible{outline:2px solid var(--brand);outline-offset:3px}
</style>
